#!/usr/bin/env node
// Muse Code native plugin bundle (muse/): Muse requires a plugin root to
// hold exactly one nested host manifest (.muse-plugin/, .codex-plugin/, or
// .claude-plugin/), and the repo root ships all three, so the bundle is a
// self-contained plugin root with only .muse-plugin/. Its skills and hooks
// are verbatim copies generated by scripts/build-muse-bundle.js from skills/
// and hooks/; these tests fail if the committed copies are stale. Manifest
// version is pinned with the other host manifests by check-versions.js.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { SKILLS, pairs } = require('../scripts/build-muse-bundle');

const root = path.join(__dirname, '..');
const bundle = path.join(root, 'muse');
const manifest = JSON.parse(fs.readFileSync(path.join(bundle, '.muse-plugin', 'plugin.json'), 'utf8'));

test('Muse manifest is native and points at the six skills in the bundle', () => {
  assert.equal(manifest.schemaVersion, 1);
  assert.equal(manifest.name, 'ponytail');
  assert.deepEqual(manifest.compat, { source: 'native', manifestDir: '.muse-plugin' });
  assert.deepEqual(manifest.capabilities.skills.map((s) => s.id), SKILLS);
  for (const skill of manifest.capabilities.skills) {
    assert.equal(skill.path, `skills/${skill.id}/SKILL.md`);
  }
});

test('Muse hooks reuse the shared lifecycle scripts, one source per hook', () => {
  const byEvent = Object.fromEntries(manifest.capabilities.hooks.map((h) => [h.event, h]));
  assert.deepEqual(Object.keys(byEvent).sort(), ['SessionStart', 'SubagentStart', 'UserPromptSubmit']);
  const sources = manifest.capabilities.hooks.map((h) => h.command[1]);
  assert.equal(new Set(sources).size, sources.length, 'hook source paths must not be shared');
  for (const hook of manifest.capabilities.hooks) {
    assert.equal(hook.command[0], 'node');
    assert.ok(fs.existsSync(path.join(bundle, hook.command[1])), `${hook.command[1]} must ship in the bundle`);
  }
});

test('bundle holds exactly one nested host manifest, so Muse reports no diagnostics', () => {
  assert.ok(fs.existsSync(path.join(bundle, '.muse-plugin', 'plugin.json')));
  assert.ok(!fs.existsSync(path.join(bundle, '.claude-plugin')), 'rival Claude manifest must stay out of the bundle');
  assert.ok(!fs.existsSync(path.join(bundle, '.codex-plugin')), 'rival Codex manifest must stay out of the bundle');
});

test('committed bundle copies match skills/ and hooks/ (stale: node scripts/build-muse-bundle.js)', () => {
  for (const [src, dst] of pairs()) {
    const expected = fs.readFileSync(path.join(root, src), 'utf8').replace(/\r\n/g, '\n');
    const onDisk = fs.readFileSync(path.join(root, dst), 'utf8').replace(/\r\n/g, '\n');
    assert.equal(onDisk, expected, `${dst} drifted from ${src}`);
  }
});

test('Muse Code install is documented in INSTALL.md and the portability map', () => {
  const install = fs.readFileSync(path.join(root, 'INSTALL.md'), 'utf8');
  assert.match(install, /## Muse Code/);
  assert.match(install, /muse plugins install \.\/ponytail\/muse/);
  assert.match(install, /muse plugins approve ponytail/);
  const portability = fs.readFileSync(path.join(root, 'docs', 'agent-portability.md'), 'utf8');
  assert.match(portability, /\| Muse Code \(Meta\) \| `muse\/\.muse-plugin\/plugin\.json`/);
});
